artifacts.content:
type WorkerProfile = {
  id: string
  description: string
  systemPrompt?: string
  model?: string
  tools?: string[]
  permissions?: Record<string, string>
  backendHints?: {
    runtime?: string
    effort?: 'low' | 'medium' | 'high'
    background?: boolean
  }
}

type WorkerRequest = {
  workerProfileId: string
  prompt: string
  outputSchema: object
  contextFiles?: string[]
  attachments?: string[]
  timeoutMs?: number
  metadata?: Record<string, unknown>
}

type WorkerResult<T = unknown> = {
  status: 'complete' | 'partial' | 'failed'
  structured: T | null
  rawText: string
  events?: unknown[]
  usage?: {
    inputTokens?: number
    outputTokens?: number
    durationMs?: number
    costUsd?: number
  }
  error?: {
    code: string
    message: string
    retryable: boolean
  }
}

interface WorkerBackend {
  name: string
  capabilities(): {
    nativeSchema: boolean
    streaming: boolean
    background: boolean
    isolatedContext: boolean
    toolsConfigurable: boolean
    permissionsConfigurable: boolean
  }
  execute<T>(request: WorkerRequest): Promise<WorkerResult<T>>
}
